[
  {
    "statement": "No studies have directly compared the cost-effectiveness of different bracken control methods in shrublands.",
    "citations": []
  },
  {
    "statement": "Several methods have been evaluated for their effectiveness in controlling bracken.",
    "citations": []
  },
  {
    "statement": "One systematic review found that the herbicide asulam reduced bracken abundance if applied repeatedly.",
    "citations": [
      "105"
    ]
  },
  {
    "statement": "Cutting may be equally effective as using herbicide for bracken control.",
    "citations": [
      "105"
    ]
  },
  {
    "statement": "Herbicide application with asulam reduced bracken biomass or cover in some randomized, controlled studies.",
    "citations": [
      "1652"
    ]
  },
  {
    "statement": "Cutting has been shown to reduce bracken cover or biomass in some studies.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "Neither cutting nor herbicide application was consistently effective across all studies.",
    "citations": []
  },
  {
    "statement": "Some studies found no effect on bracken abundance from either cutting or herbicide application.",
    "citations": []
  },
  {
    "statement": "Cutting followed by herbicide application has been shown to reduce bracken biomass or cover.",
    "citations": [
      "1654"
    ]
  },
  {
    "statement": "No studies have evaluated combinations of herbicide with grazing.",
    "citations": [
      "1658"
    ]
  },
  {
    "statement": "No studies have evaluated combinations of herbicide with seeding shrubland plants.",
    "citations": [
      "1661"
    ]
  },
  {
    "statement": "Bracken bruising has been found to increase bracken cover.",
    "citations": [
      "1726"
    ]
  }
]

[
  {
    "statement": "There is no available evidence on the success rate of legally protecting specific plant species from gathering in shrublands.",
    "citations": [
      "1612"
    ]
  },
  {
    "statement": "Systematic searches of scientific journals and reports have not found any studies that directly evaluated the effectiveness of legally protecting specific plant species from gathering.",
    "citations": [
      "1612"
    ]
  },
  {
    "statement": "It is not possible to assess whether legal protection is effective or has any harmful impacts on plant species conservation in shrubland habitats.",
    "citations": [
      "1612"
    ]
  },
  {
    "statement": "The evidence base for the conservation intervention of legally protecting specific plant species from gathering remains completely unstudied.",
    "citations": [
      "1612"
    ]
  }
]
